const paths={brand:'M13 3L5 11q-3 3 0 5t5-1l4-4M11 21l8-8q3-3 0-5t-5 1l-4 4',cash:'M4 8h16v13H4zM3 3h18v5H3zM8 12h8m-8 4h3',history:'M3 12a9 9 0 1 0 3-7M3 3v5h5M12 7v6l4 2',chart:'M4 20V10m6 10V4m6 16v-7m5 7H2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',camera:'M3 7h4l2-3h6l2 3h4v14H3zM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',save:'M4 3h14l3 3v15H3V3zM7 3v6h10V3M7 21v-8h10v8',voice:'M4 10h4l5-5v14l-5-5H4zM17 8q6 4 0 8',plus:'M12 4v16M4 12h16',close:'M6 6l12 12M18 6L6 18',check:'M5 12l4 4L20 5',file:'M5 2h10l5 5v15H5zM14 2v6h6M8 13h8m-8 4h8'};
const ico=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.cash}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cashBrowseDay=key(),posBrowseDay=key(),rangeCash='all';const expandedHistory=new Set();
let S={settings:{theme:'system',cashboxes:[],denoms:[]},entries:[],drafts:[],revisions:[]},F=null,tab='count',selectedCash='main',selectedDate=key(),period='week',reportCash='all',modal=false,timer,toastTimer,photoContext=null,photo=null,currentReport=null;
const $=s=>document.querySelector(s);
function call(method,...args){if(!window.KasaDenge)throw Error('Android uygulaması gerekli.');const r=JSON.parse(window.KasaDenge[method](...args));if(!r.ok)throw Error(r.error);return r.data;}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function cashName(r){return cfg().cashboxes.find(b=>b.id===r.cashId)?.name||r.cashName||'Kasa';}
function syncNames(){for(const field of ['entries','pos','revisions','posRevisions','posTotals'])if(S[field])S[field]=S[field].map(r=>({...r,cashName:cashName(r)}));if(F)F.cashName=cashName(F);}
function cfg(){return S.settings;}
function box(){return cfg().cashboxes.find(b=>b.id===selectedCash)||cfg().cashboxes.find(b=>b.active);}
function entry(){return S.entries.find(r=>r.cashId===selectedCash&&r.date===selectedDate);}
function loadForm(){const b=box();if(!b){F=null;selectedCash="";return;}selectedCash=b.id;const r=entry(),draft=S.drafts.find(d=>d.cashId===selectedCash&&d.date===selectedDate);if(draft&&draft.lines&&draft.counts){F=JSON.parse(JSON.stringify(draft));try{if(money(F.otherText||'0')===0)F.otherText='';}catch{}F.cashName=b.name;return;}const lines=(r?r.lines:cfg().denoms.filter(d=>d.active)).map(l=>({id:l.id,label:l.label,value:l.value,kind:l.kind}));F={cashId:b.id,cashName:b.name,date:selectedDate,expectedText:r?decimal(r.expected):'',advanceText:decimal(r?r.advance:b.advance),otherText:r&&r.other?decimal(r.other):'',lines,counts:Object.fromEntries(lines.map(l=>[l.id,r?String(r.lines.find(x=>x.id===l.id)?.count||0):''])),note:r?.note||'',reason:'',baseRevision:r?.revision||0};}
function refresh(reset=false){try{if(window.KasaDenge)S=call('state');if(reset||!F)loadForm();syncNames();theme();render();}catch(e){toast(e.message);}}
function theme(){document.body.classList.toggle('dark',cfg().theme==='dark'||cfg().theme==='system'&&S.systemDark);}
function stash(){clearTimeout(timer);if(!F)return;try{call('draft',JSON.stringify(F));const i=S.drafts.findIndex(d=>d.cashId===F.cashId&&d.date===F.date);if(i>=0)S.drafts[i]=JSON.parse(JSON.stringify(F));else S.drafts.push(JSON.parse(JSON.stringify(F)));$('#draft-status')&&( $('#draft-status').textContent='Taslak cihazda saklandı');}catch(e){toast('Taslak kaydedilemedi: '+e.message);}}
function cashOptions(includeArchived=false){return cfg().cashboxes.filter(b=>includeArchived||b.active||b.id===selectedCash).map(b=>`<option value="${esc(b.id)}" ${b.id===selectedCash?'selected':''}>${esc(b.name)}${b.active?'':' · arşiv'}</option>`).join('');}
function controls(){return `<div class="cash-controls"><select id="cash" aria-label="Kasa seçimi">${cashOptions(tab!=='count')}</select><input id="day" type="date" aria-label="Kayıt Tarihi" title="Kayıt Tarihi" value="${selectedDate}" max="${key()}"></div>`;}
function resultHtml(r,full=false){return `<div class="result ${r.diff<0?'short':r.diff>0?'over':''}"><span>${r.diff<0?'Kasa eksiği':r.diff>0?'Kasa fazlası':'Kasa dengeli'}</span><b>${fmt(Math.abs(r.diff))}</b></div>${full?`<div class="panel">${[['Beklenen kasa · avans hariç',r.expected],['Avans',r.advance],['Fiziksel kasa hedefi',r.target],['Sayılan banknot',r.paper],['Adetle sayılan madeni',r.coins],['Gereken diğer bozuk',Math.max(0,r.remaining)],['Sayılan diğer bozuk',r.other],['Toplam sayılan',r.counted]].map(([l,n],i)=>`<div class="ledger-row ${i===2||i===7?'major':''}"><span>${l}</span><strong>${fmt(n)}</strong></div>`).join('')}${r.remaining<0?`<p class="warning">Adetle sayılan para hedefi ${fmt(-r.remaining)} aşıyor. Diğer bozuk ihtiyacı yok; girilen bozuk da fazlaya eklenir.</p>`:`<p class="help">${fmt(r.target)} − ${fmt(r.paper+r.coins)} = ${fmt(r.remaining)} diğer bozuk gerekir.</p>`}<div class="ledger-row"><span>Avans hariç sayılan para</span><strong>${fmt(r.net)}</strong></div></div>`:''}`;}
function emptyCash(){return '<section class="panel"><h1>Etkin Kasa Yok</h1><p>Sayım Ve POS Girişi İçin Kendi Kasanı Ekle. Önceki Kayıtlar Geçmiş Ve Analiz Bölümlerinde Korunur.</p><button class="primary" data-act="edit-box">Kasa Ekle</button></section>';}
function countScreen(){if(!F)return `<div class="hero"><h1>Kasa Sayımı</h1></div>${browseStrip('cash',cashBrowseDay)}<div id="count-focus"></div>${emptyCash()}`;const old=entry();return `<div class="hero"><h1>Kasa sayımı</h1><span class="badge">${old?'Kapanmış kayıt · r'+old.revision:'Taslak'}</span></div>${browseStrip('cash',cashBrowseDay)}<div id="count-focus"></div><h2 class="entry-heading">Yeni Sayım / Kayıt Düzenleme</h2>${controls()}<div class="draft-info"><span id="draft-status">${old?'Düzeltmeler gerekçesiyle saklanır':'Otomatik taslak kaydı açık'}</span><button data-act="reset-draft" class="text-button">Taslağı sıfırla</button></div><div class="cash-layout"><div><div class="money-fields"><label class="field"><span>Beklenen tutar · avans hariç</span><input id="expectedText" inputmode="decimal" aria-label="Beklenen tutar" placeholder="0,00" value="${esc(F.expectedText)}"></label><label class="field"><span>Avans · bu sayım için</span><input id="advanceText" inputmode="decimal" aria-label="Avans tutarı" value="${esc(F.advanceText)}"></label></div><p class="help">Kasa Farkı = Sayılan Banknot + Madeni + Diğer Bozuk − Avans − Beklenen Tutar.</p><div class="section-head"><h2>Para adetleri</h2><button class="text-button" data-act="photo">${ico('camera')} Defterden oku</button></div><div class="table-wrap"><table><thead><tr><th>Para</th><th>Adet</th><th>Tutar</th></tr></thead><tbody>${F.lines.map(l=>`<tr><td><span class="denom-chip ">${esc(denominationLabel(l))}</span></td><td class="count-cell"><button class="step" data-act="step" data-id="${esc(l.id)}" data-step="-1" aria-label="${esc(denominationLabel(l))} azalt">−</button><input class="count-input" inputmode="numeric" pattern="[0-9]*" maxlength="7" data-count="${esc(l.id)}" aria-label="${esc(denominationLabel(l))} adedi" value="${esc(F.counts[l.id])}" placeholder="0"><button class="step" data-act="step" data-id="${esc(l.id)}" data-step="1" aria-label="${esc(denominationLabel(l))} artır">+</button></td><td id="line-${esc(l.id)}">—</td></tr>`).join('')}</tbody></table><div class="total-row"><span>Adetle sayılan toplam</span><strong id="counted-lines">—</strong></div></div><label class="field"><span>Diğer bozuk para <small>· yukarıda saydıkların hariç</small></span><input id="otherText" aria-label="Diğer bozuk para" inputmode="decimal" placeholder="Boş Bırakırsan 0 TL" value="${esc(F.otherText)}"></label><div id="other-needed" class="other-needed"></div><p class="help">5 TL (Madeni) adedini buraya tekrar ekleme. Eklediğin diğer madeni para türleri de bu alanın dışında kalır.</p></div><div class="cash-side"><div id="live-summary"></div><label class="field"><span>Sayım notu · isteğe bağlı</span><textarea id="note" maxlength="1000" aria-label="Sayım notu" placeholder="Kasa farkı açıklaması…">${esc(F.note)}</textarea></label>${old?`<label class="field edit-reason"><span>Düzeltme gerekçesi · zorunlu</span><input id="reason" aria-label="Düzeltme gerekçesi" maxlength="300" value="${esc(F.reason)}" placeholder="Örn. 100 TL adedi yeniden sayıldı"></label>`:''}<div class="actions"><button data-act="speak">${ico('voice')} Sonucu seslendir</button><button data-act="photo">${ico('camera')} Fotoğraftan aktar</button></div><button class="primary full" data-act="confirm">${ico('save')} ${old?'Düzeltmeyi kontrol et':'Sonucu kontrol et ve kaydet'}</button><p class="help">Kaydetmeden önce son onayın istenir. İnternet gerekmez.</p></div></div>`;}
function live(){liveValues();renderDailyReconciliation();decorateLabels();}
function liveValues(){if(tab!=='count'||!F)return;let subtotal=0;for(const l of F.lines){try{const v=l.value*count(F.counts[l.id]);subtotal+=v;const el=document.getElementById('line-'+l.id);if(el)el.textContent=fmt(v);}catch{const el=document.getElementById('line-'+l.id);if(el)el.textContent='Geçersiz';}}$('#counted-lines')&&($('#counted-lines').textContent=fmt(subtotal));try{const r=record(F);const needed=$('#other-needed');if(needed)needed.innerHTML=`<span>Kasanın Tutması İçin Gereken Diğer Bozuk</span><b>${fmt(Math.max(0,r.remaining))}</b><small>${fmt(r.expected)} + ${fmt(r.advance)} − ${fmt(r.paper+r.coins)}${r.remaining<0?' · Adetle Sayılan Para Hedefi Aşıyor':''}</small>`;$('#live-summary').innerHTML=resultHtml(r,true);const mini=$('#mini-cash');if(mini)mini.innerHTML=`<span>Gereken diğer bozuk <b>${fmt(Math.max(0,r.remaining))}</b></span><strong class="${r.diff<0?'neg':'pos'}">${r.diff===0?'Dengeli':fmt(Math.abs(r.diff))+(r.diff<0?' eksik':' fazla')}</strong>`;}catch(e){const needed=$('#other-needed');if(needed)needed.textContent='Gereken Bozuk İçin Beklenen Tutarı Girin.';$('#live-summary').innerHTML=`<div class="panel"><h2>Sayım sonucu</h2><p class="help">${esc(e.message)}</p></div>`;const mini=$('#mini-cash');if(mini)mini.textContent='Hesaplamak için beklenen tutarı ve geçerli adetleri gir.';}}
function cashHistoryDays(rows){const days=historyDays(rows);return `${days.map(d=>`<section class="panel history-day" data-day="${d.date}"><div class="history-top"><h2>${displayDate(d.date)}</h2><b class="${d.total<0?'neg':d.total>0?'pos':''}">${signedMoney(d.total)}</b></div><p class="help">${d.rows.length} Kasa · Günlük Genel Toplam</p>${d.rows.map(r=>`<article class="history-card"><div class="history-top"><b>${esc(r.cashName)}</b><b class="${r.diff<0?'neg':r.diff>0?'pos':''}">${signedMoney(r.diff)}</b></div><small>Avans Hariç Sayım ${fmt(r.net)} · Hedef ${fmt(r.target)} · r${r.revision}</small>${r.note?`<p class="help">${esc(r.note)}</p>`:''}${r.reason?`<p class="help">Son Düzeltme: ${esc(r.reason)}</p>`:''}<div class="history-actions"><button data-act="open-entry" data-date="${r.date}" data-cash="${esc(r.cashId)}">Aç / Gerekçeli Düzelt</button>${r.revision>1?`<button data-act="revisions" data-id="${esc(r.id)}">Eski Halleri (${r.revision-1})</button>`:''}<button class="delete-link" data-act="delete-entry" data-id="${esc(r.id)}">Sil</button></div></article>`).join('')}<button class="delete-link" data-act="delete-day" data-date="${d.date}">Bu Günün Sayımlarını Sil</button></section>`).join('')||'<div class="empty"><h3>Henüz Kapanış Yok</h3><p>Kaydettiğin Sayımlar Gün Gün Burada Görünür.</p></div>'}`;}
let deleteTargets=null;
function askDelete(rows){if(!rows.length)throw Error('Silinecek Kayıt Bulunamadı.');deleteTargets=rows.map(r=>({id:r.id,revision:r.revision,savedAt:r.savedAt}));openSheet('Sayım Silme Onayı',`<p class="warning">Aşağıdaki ${rows.length} Sayım Kaydı, İlgili Taslakları Ve Eski Düzeltmeleri Kalıcı Olarak Silinecek. POS Kayıtları Silinmez.</p>${rows.map(r=>`<div class="ledger-row"><span>${displayDate(r.date)} · ${esc(r.cashName)}</span><strong>${signedMoney(r.diff)}</strong></div>`).join('')}<div class="ledger-row major"><span>Silinecek Kayıtların Toplam Farkı</span><strong>${signedMoney(rows.reduce((n,r)=>n+r.diff,0))}</strong></div><p class="help">Silinen Sayımlar Analizlerden Ve Günlük Toplamdan Çıkar. Önceden Alınmış Yedek Dosyaları Değişmez.</p><button class="primary full danger-button" data-act="delete-final">Evet, ${rows.length===1?'Kaydı':'Bu Sayımları'} Sil</button><button class="full cancel-delete" data-act="dismiss">Vazgeç</button>`);}
function reportScreen(){const cashId=reportCash==='all'?null:reportCash,a=cashReport(S.entries,cashId,period,selectedDate),p=posReport(allPos(),cashId,period,selectedDate),comments=analysisInsights(S.entries,allPos(),cashId,period,selectedDate),detail=reportDetailsScreen(),body=detail.slice(detail.indexOf('<section class="panel">'));const options='<option value="all" '+(reportCash==='all'?'selected':'')+'>Tüm Kasalar</option>'+cfg().cashboxes.map(b=>`<option value="${esc(b.id)}" ${reportCash===b.id?'selected':''}>${esc(b.name)}</option>`).join('');return `<div class="toolbar"><h1>Analiz Ve Yorumlar</h1></div><div class="cash-controls"><select id="report-cash" aria-label="Analiz Kasası">${options}</select><input id="day" type="date" aria-label="Analiz Tarihi" value="${selectedDate}" max="${key()}"></div><label class="field"><span>Dönem</span><select id="period" aria-label="Rapor Dönemi">${[['day','Günlük'],['week','Bu Hafta'],['lastweek','Geçen Hafta'],['month','Bu Ay'],['lastmonth','Geçen Ay']].map(([v,l])=>`<option value="${v}" ${period===v?'selected':''}>${l}</option>`).join('')}</select></label><p class="help">Dönem: ${displayDate(a.w.start)} – ${displayDate(a.w.end)}. Günlük Yorumun Tarihi: ${displayDate(selectedDate)}. Yalnız Kaydedilmiş Veriler Kullanılır.</p>${weekdayChart('Nakit · Haftanın Günleri',weekdayAverages(S.entries,'net',selectedDate,cashId),'Avans Hariç Kayıtlı Sayım')}${weekdayChart('POS · Haftanın Günleri',weekdayAverages(allPos(),'total',selectedDate,cashId),'İşlem Gününe Göre POS Satışı')}<section class="panel analysis-comments"><h2>Nakit Yorumları</h2>${comments.filter(c=>!c.title.startsWith('POS')).map(commentCard).join('')}</section><section class="panel analysis-comments"><h2>POS Yorumları</h2>${comments.filter(c=>c.title.startsWith('POS')).map(commentCard).join('')}</section><section class="panel analysis-summary"><h2>Döneme Kısa Bakış</h2><div class="metrics">${[['Nakit · Avans Hariç',a.stats.net],['Nakit · Beklenen',a.stats.expected],['POS · Satış',p.stats.total],['POS · Planlanan Yatış',p.due.total]].map(([label,value])=>`<div class="metric-card"><small>${label}</small><b>${fmt(value)}</b></div>`).join('')}</div><p class="help">Nakit Ve POS Ayrı Ölçümlerdir; Bu Tutarlar Kâr Değildir.</p></section><details class="panel analysis-details"><summary>Ayrıntılı Tablolar Ve Karşılaştırmalar</summary>${body}</details>`;}
function reportDetailsScreen(){const cashId=reportCash==='all'?null:reportCash,a=cashReport(S.entries,cashId,period,selectedDate),p=posReport(allPos(),cashId,period,selectedDate),s=a.stats;currentReport=a.current;const names=id=>esc(cashName({cashId:id}));const options='<option value="all" '+(reportCash==='all'?'selected':'')+'>Tüm Kasalar</option>'+cfg().cashboxes.map(b=>`<option value="${esc(b.id)}" ${reportCash===b.id?'selected':''}>${esc(b.name)}</option>`).join('');const m=(label,value,cls='')=>`<div class="metric-card"><small>${label}</small><b class="${cls}">${value}</b></div>`;const cards=(rows,id=false)=>rows.map(r=>`<tr><td>${id?names(r.cashId):displayDate(r.date)}</td><td>${fmt(r.credit)}</td><td>${fmt(r.debit)}</td><td>${fmt(r.total)}</td></tr>`).join('');const table=(title,rows,id=false)=>`<section class="panel"><h2>${title}</h2><div class="table-wrap"><table><thead><tr><th>${id?'Kasa':'Tarih'}</th><th>Kredi Kartı</th><th>Debit Kart</th><th>Toplam</th></tr></thead><tbody>${cards(rows,id)||'<tr><td colspan="4">Kayıt Yok</td></tr>'}</tbody></table></div></section>`;return `<div class="toolbar"><h1>Nakit Ve POS Analizi</h1></div><div class="cash-controls"><select id="report-cash" aria-label="Analiz Kasası">${options}</select><input id="day" type="date" aria-label="Analiz Tarihi" value="${selectedDate}" max="${key()}"></div><label class="field"><span>Dönem</span><select id="period" aria-label="Rapor Dönemi">${[['day','Günlük'],['week','Bu Hafta'],['lastweek','Geçen Hafta'],['month','Bu Ay'],['lastmonth','Geçen Ay']].map(([v,l])=>`<option value="${v}" ${period===v?'selected':''}>${l}</option>`).join('')}</select></label><p class="help">${displayDate(a.w.start)} – ${displayDate(a.w.end)} · ${reportCash==='all'?'Tüm Kasalar':names(reportCash)}. İçinde bulunduğun dönemde seçili tarihe kadar kayıtlar gösterilir.</p><section class="panel"><h2>Nakit Özeti · Avans Hariç</h2><div class="metrics">${m('Avans Hariç Sayım',fmt(s.net))}${m('Beklenen Tutar',fmt(s.expected))}${m('Toplam Kasa Eksiği',fmt(s.shortage),'neg')}${m('Toplam Kasa Fazlası',fmt(s.surplus),'pos')}${m('Eksik Çıkan Gün',s.shortDays,'neg')}${m('Fazla Çıkan Gün',s.overDays,'pos')}${m('Dengeli Gün',s.balancedDays)}${m('Kayıtlı Gün Ortalaması',s.avg===null?'—':fmt(s.avg))}</div><p class="help">${s.days} kayıtlı gün · ${s.closings} kasa kapanışı. Tüm kasalarda gün durumu o günün toplam farkıdır; kasaların eksiği ve fazlası tutar olarak birbirinden düşülmez.</p><div class="insight"><h3>Önceki Döneme Göre</h3><p>${a.comparison.pairs?`${a.comparison.pairs} eşleşen kasa/gün kaydında sayım ${fmt(Math.abs(a.comparison.delta))} ${a.comparison.delta<0?'daha düşük':a.comparison.delta>0?'daha yüksek':'ile aynı'}.`:'Aynı kasaya ait eşleşen geçmiş kayıt yok; eksik günler sıfır sayılmadı.'}</p><small>${displayDate(a.w.previousStart)} – ${displayDate(a.w.previousEnd)} ile eşleştirilir.</small></div></section><section class="panel"><h2>Nakit · Kasa Bazında</h2><div class="table-wrap"><table><thead><tr><th>Kasa</th><th>Sayım · Avans Hariç</th><th>Eksik</th><th>Fazla</th></tr></thead><tbody>${a.boxes.map(r=>`<tr><td>${names(r.cashId)}</td><td>${fmt(r.net)}</td><td class="neg">${fmt(r.shortage)}</td><td class="pos">${fmt(r.surplus)}</td></tr>`).join('')||'<tr><td colspan="4">Kayıt Yok</td></tr>'}</tbody></table></div></section><section class="panel"><h2>Nakit · Günlük Toplam</h2><div class="table-wrap"><table><thead><tr><th>Tarih</th><th>Sayım · Avans Hariç</th><th>Beklenen</th><th>Eksik / Fazla</th></tr></thead><tbody>${a.days.map(r=>`<tr><td>${displayDate(r.date)}</td><td>${fmt(r.net)}</td><td>${fmt(r.expected)}</td><td><span class="neg">${fmt(r.shortage)} Eksik</span><br><span class="pos">${fmt(r.surplus)} Fazla</span></td></tr>`).join('')||'<tr><td colspan="4">Kayıt Yok</td></tr>'}</tbody></table></div></section><details class="panel"><summary>Nakit · Kasa Ve Gün Ayrıntıları</summary>${a.current.map(r=>`<div class="ledger-row"><span>${displayDate(r.date)} · ${esc(r.cashName)}</span><strong>${fmt(r.net)}<br><small>${fmt(r.diff)} Fark</small></strong></div>`).join('')||'<p class="help">Kayıt Yok</p>'}</details><section class="insight"><h3>Aynı Hafta Gününe Göre Nakit</h3><p>${a.sameDay.count?`Önceki ${a.sameDay.count} aynı hafta gününün sayım ortalaması ${fmt(a.sameDay.avg)}, ortancası ${fmt(a.sameDay.median)}.${a.sameDay.delta!==null?' Seçili gün farkı '+fmt(a.sameDay.delta)+'.':''}`:'Aynı hafta günü için geçmiş sayım yok.'}</p><small>Son 8 geçmiş aynı gün; seçili gün ortalamaya katılmaz. ${a.sameDay.count<3?'Az kayıt var; güçlü eğilim yorumu yapılmaz.':''} Kayıtlı kasalar ve günler esas alınır.</small></section><section class="panel"><h2>POS Özeti · İşlem Tarihine Göre</h2><div class="metrics">${m('Kredi Kartı',fmt(p.stats.credit))}${m('Debit Kart',fmt(p.stats.debit))}${m('Toplam POS Satışı',fmt(p.stats.total))}${p.stats.unallocated?m('Dağılım Bekleyen',fmt(p.stats.unallocated)):''}${m('Önceki Dönem POS',fmt(p.prior.total))}</div><p class="help">${p.sales.length} gün sonu raporu. World puan kredi kartı grubunda; yurt dışı debit, debit grubunda ve +21 gün vadelidir. Önceki döneme göre kayıtlı satış farkı ${fmt(p.stats.total-p.prior.total)}. Eksik raporlar sonucu etkiler; eksik günler sıfır satış demek değildir.</p><div class="insight"><h3>Aynı Hafta Gününe Göre POS</h3><p>${p.sameDay.count?`Önceki ${p.sameDay.count} aynı hafta gününün kayıtlı satış ortalaması ${fmt(p.sameDay.avg)}.${p.sameDay.delta!==null?' Seçili gün farkı '+fmt(p.sameDay.delta)+'.':''}`:'Karşılaştırılacak aynı hafta günü raporu yok.'}</p><small>Son 8 geçmiş aynı gün; seçili gün ortalamaya katılmaz. ${p.sameDay.count<3?'Az kayıt var; güçlü eğilim yorumu yapılmaz.':''}</small></div></section>${table('POS Satışları · Kasa Bazında',p.boxes,true)}${table('POS Satışları · Günlük Toplam',p.days)}<details class="panel"><summary>POS · Kasa Ve Gün Ayrıntıları</summary>${p.sales.map(r=>`<div class="ledger-row"><span>${displayDate(r.date)} · ${esc(r.cashName)}<br><small>${esc(r.terminal)}</small></span><strong>${fmt(r.total)}</strong></div>`).join('')||'<p class="help">Kayıt Yok</p>'}</details><section class="panel"><h2>POS Tahsilatı · Vade Tarihine Göre</h2><div class="metrics">${m('Yatacak Kredi Kartı',fmt(p.due.credit))}${m('Yatacak Debit Kart',fmt(p.due.debit))}${m('Toplam Beklenen',fmt(p.due.total))}${m('Önceki Dönem Beklenen',fmt(p.priorDue.total))}</div><p class="help">Bunlar banka hesabına yatması planlanan tutarlardır; nakit sayımına eklenmez. Kredi/World/yurt dışı debit +21, diğer debit +16 takvim günü. Komisyon yok.</p></section>${table('POS Tahsilatı · Kasa Bazında',p.dueBoxes,true)}${table('POS Tahsilatı · Günlük Toplam',p.dueDays)}<p class="help">Nakit sayımı satış kârı değildir. Taslaklar ve eski revizyonlar analizlere katılmaz. POS satış günü ile tahsilat günü ayrı ölçümlerdir.</p><div class="actions no-print"><button data-act="csv">Nakit Dönemini CSV Aktar</button><button data-act="print">PDF / Yazdır</button></div>`;}
function settingsScreen(){return `<div class="toolbar"><h1>Ayarlar</h1><small>İşletmem Kasa 1.0.17</small></div><section class="settings-card"><h2>Görünüm</h2><div class="theme-options">${[['light','Açık'],['dark','Koyu'],['system','Sistem']].map(([v,l])=>`<button data-act="theme" data-theme="${v}" class="theme-option ${cfg().theme===v?'active':''}">${l}</button>`).join('')}</div></section><section class="settings-card"><div class="photo-head"><h2>Kasalar ve avanslar</h2><button class="text-button" data-act="edit-box">+ Kasa ekle</button></div>${cfg().cashboxes.map(b=>`<div class="settings-row"><div><b>${esc(b.name)} ${b.active?'':'· arşiv'}</b><small>Varsayılan avans ${fmt(b.advance)} · ${b.posMode==='total'?'Tek Toplam POS':'Ayrıntılı POS'}</small></div><div><button data-act="edit-box" data-id="${esc(b.id)}">Düzenle</button>${b.active?`<button data-act="remove-box" data-id="${esc(b.id)}">Kasayı Sil</button>`:""}</div></div>`).join('')}<p class="help">Her kasa/gün avansı kayda ayrıca yazılır. Ayar değişikliği eski kapanışları değiştirmez.</p></section><section class="settings-card"><div class="photo-head"><h2>Para türleri</h2><button class="text-button" data-act="edit-denom">+ Para ekle</button></div>${cfg().denoms.map(d=>`<div class="settings-row"><div><b>${esc(denominationLabel(d))} ${d.active?'':'· kapalı'}</b><small>${d.kind==='paper'?'Kâğıt para':'Madeni para'} · ${fmt(d.value)}</small></div><button data-act="edit-denom" data-id="${esc(d.id)}">Düzenle</button></div>`).join('')}<p class="help">Başlangıç sırası: 200, 100, 50, 20, 10, 5 TL kâğıt ve hemen altında 5 TL (Madeni). Kaldırılan türlerin eski kayıtları korunur.</p></section><section class="settings-card"><h2>Yerel yedek ve rapor</h2><p>Kayıtlar SQLite veritabanında, cihazında saklanır. Uygulamayı silmeden veya telefon değiştirmeden önce yedek al.</p><div class="actions"><button data-act="export">Yedeği kaydet</button><button data-act="import">Yedekten ekle</button></div><p class="help">Yedek açık JSON'dur; kasalara ait tutarlar içerir. İçe aktarma mevcut kapanışların üzerine yazmaz. Arşiv ve düzeltmeler dışa aktarılan dosyada saklanır; içe aktarma güncel kapanışları ekler.</p></section><section class="settings-card"><h2>Fotoğraftan sayım</h2><p>Yazı tanıma cihaz üzerinde çalışır. El yazısı ve silik fotoğraflarda hata olabilir. Önerilen değerler onayından sonra forma aktarılır; kayıt için ayrıca kapanış onayı gerekir. Fotoğraf veritabanında veya yedekte tutulmaz.</p><h2 style="margin-top:18px">Sesli teyit</h2><p>Sonucu seslendir düğmesi, telefonda yüklü çevrimdışı Türkçe sesle çalışır. Ses yoksa telefonun metin okuma ayarlarından yükleyebilirsin.</p></section>`;}
function render(){const y=scrollY;$('#app').innerHTML=`<main class="shell ${tab==='count'?'count-shell':''}"><header class="topbar"><div class="brand"><div class="brand-mark">${ico('brand')}</div><div><div class="brand-name">İşletmem Kasa</div><small>NAKİT · POS · MUTABAKAT</small></div></div><button class="icon-button no-print" data-act="tab" data-tab="settings" aria-label="Ayarları aç">${ico('settings')}</button></header>${tab==='count'?countScreen():tab==='pos'?posScreen():tab==='history'?historyScreen():tab==='report'?reportScreen():settingsScreen()}</main><nav class="bottom-nav" aria-label="Ana menü">${[['count','cash','Sayım'],['pos','file','POS'],['history','history','Geçmiş'],['report','chart','Analiz'],['settings','settings','Ayarlar']].map(([v,i,l])=>`<button class="nav-button ${tab===v?'active':''}" data-act="tab" data-tab="${v}">${ico(i)}${l}</button>`).join('')}</nav>${tab==='count'?'<div class="mini-cash no-print" id="mini-cash"></div>':''}`;live();decorateDates();decorateAmounts();decorateLabels();window.scrollTo(0,y);}
function openSheet(title,html){modal=true;document.body.classList.add('modal-open');$('#modal-root').innerHTML=`<div class="overlay"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="sheet-handle"></div><div class="sheet-head"><h2 id="sheet-title">${title}</h2><button class="icon-button" data-act="dismiss" aria-label="Kapat">${ico('close')}</button></div>${html}</section></div>`;decorateDates();decorateAmounts();decorateLabels();}
function dismiss(){deleteTargets=null;modal=false;$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');}
function confirm(){const r=record(F);if(F.baseRevision&&F.reason.trim().length<3)throw Error('Düzeltme gerekçesini en az 3 karakterle yazın.');openSheet('Kapanış onayı',`<p class="help">${esc(F.cashName)} · ${displayDate(F.date)} ${F.baseRevision?'· gerekçeli düzeltme':''}</p>${resultHtml(r,true)}<p class="help">Bu tutarları kontrol ettim ve kaydetmeyi onaylıyorum.</p><button class="primary full" data-act="save-final">${ico('check')} Onaylıyorum, kaydet</button>`);}
function editBox(id){const b=cfg().cashboxes.find(b=>b.id===id);openSheet(b?'Kasayı düzenle':'Yeni kasa',`<form id="box-form" data-id="${esc(id||'')}"><label class="field"><span>Kasa adı</span><input name="name" aria-label="Kasa adı" maxlength="60" required value="${esc(b?.name||'')}"></label><label class="field"><span>Varsayılan avans</span><input name="advance" aria-label="Varsayılan avans" inputmode="decimal" required value="${b?decimal(b.advance):'1500,00'}"></label><label class="field"><span>POS Giriş Türü</span><select name="posMode" aria-label="POS Giriş Türü"><option value="detailed" ${b?.posMode!=='total'?'selected':''}>Fiş Gibi Ayrıntılı · Kredi / Debit</option><option value="total" ${b?.posMode==='total'?'selected':''}>Tek Toplam · Sonradan Tahsilatla Ayır</option></select></label><label class="switch-label"><input type="checkbox" name="active" ${b?.active!==false?'checked':''}>Kasa etkin</label><p class="help">Kapatılan kasa arşivde korunur; eski kapanışları silinmez.</p><p class="form-error" role="alert"></p><button class="primary full" type="submit">Kaydet</button></form>`);}
function editDenom(id){const d=cfg().denoms.find(d=>d.id===id);openSheet(d?'Para türünü düzenle':'Para türü ekle',`<form id="denom-form" data-id="${esc(id||'')}"><label class="field"><span>Görünen ad</span><input name="label" aria-label="Para adı" maxlength="50" required value="${esc(d?denominationLabel(d):'')}"></label><label class="field"><span>Değeri · TL</span><input name="value" aria-label="Para değeri" inputmode="decimal" required value="${d?decimal(d.value):''}"></label><label class="field"><span>Tür</span><select name="kind" aria-label="Para türü"><option value="paper" ${d?.kind!=='coin'?'selected':''}>Kâğıt para</option><option value="coin" ${d?.kind==='coin'?'selected':''}>Madeni para</option></select></label><label class="switch-label"><input type="checkbox" name="active" ${d?.active!==false?'checked':''}>Yeni sayımlarda kullan</label><p class="help">Mevcut taslaklar kendi para listelerini korur. Güncel liste için yeni sayım açın veya taslağı sıfırlayın.</p><p class="form-error" role="alert"></p><button class="primary full" type="submit">Kaydet</button></form>`);}
window.photoResult=result=>{if(!photoContext||result.token!==photoContext.token){toast('Önceki fotoğraf okuması geçersizleşti; güncel fotoğrafı bekleyin veya tekrar seçin.');return;}if(photoContext.kind==='pos'){if(photoContext.cashId!==selectedCash){toast('Kasa değişti; tekrar fotoğraf seçin.');return;}posPhoto(result);return;}photo={...result,context:photoContext};let suggest=cashbookSuggestions(result,F.lines);const cashMatch=matchBookCash(suggest.cashNumber,cfg().cashboxes);const targetCash=cashMatch.cashId||F.cashId,targetDay=suggest.date||F.date,old=S.entries.find(r=>r.cashId===targetCash&&r.date===targetDay),b=cfg().cashboxes.find(b=>b.id===targetCash);const draft=targetCash===F.cashId&&targetDay===F.date?F:S.drafts.find(d=>d.cashId===targetCash&&d.date===targetDay);let bookAdvance=old?.advance??b?.advance;if(draft)try{bookAdvance=money(draft.advanceText);}catch{bookAdvance=undefined;}suggest=cashbookSuggestions(result,F.lines,{advance:bookAdvance,counts:draft?.counts||(old?Object.fromEntries(old.lines.map(l=>[l.id,l.count])):{})});photo.suggestion=suggest;photo.estimateContext={cashId:targetCash,date:targetDay};openSheet('Fotoğrafı kontrol et',`<p class="help">Okunan değerler öneridir. El yazısını özellikle kontrol et. Boş bırakılan alanlar formdaki mevcut değeri korur.</p><img class="ocr-preview" src="${esc(result.image)}" alt="Seçilen kasa defteri fotoğrafı"><details><summary>Okunan metin</summary><pre class="ocr-text">${esc(result.text||'Metin bulunamadı; alanları elle doldurabilirsin.')}</pre></details><form id="photo-form">${suggest.template?`<p class="help">${suggest.cashNumber?'Defterde Okunan: '+suggest.cashNumber+'. Kasa':'Defterde Kasa Numarası Net Okunamadı.'}${cashMatch.candidates.length>1?' Birden Fazla Kasa Eşleşti; Seçimini Yap.':''}</p><label class="field"><span>Kaydın Kasası</span><select name="cashId" aria-label="Fotoğraf Kasası" required><option value="">Kasa Seçin</option>${cfg().cashboxes.map(b=>`<option value="${esc(b.id)}" ${cashMatch.cashId===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><p class="help">Üst Satırdaki Defter Tarihi Kullanılır; Fotoğrafın Köşesindeki Çekim Tarihi Kullanılmaz.</p>`:`<input type="hidden" name="cashId" value="${esc(F.cashId)}">`}<label class="field"><span>Tarih</span><input type="date" name="date" aria-label="Fotoğraf tarihi" ${suggest.template?'required':''} value="${esc(suggest.date||'')}"></label>${[['expected','Beklenen tutar · avans hariç'],['advance','Avans'],['other','Diğer bozuk · adetle sayılanlar hariç']].map(([v,l])=>`<label class="field"><span>${l}</span><input name="${v}" inputmode="decimal" aria-label="Fotoğraf ${v}" value="${esc(suggest[v]||'')}" placeholder="Okunmadı · mevcut değer korunur"><small class="ocr-field-state">${esc(suggest.sources?.[v]||'')}</small></label>`).join('')}<div class="ocr-counts">${F.lines.map(l=>`<label class="field"><span>${esc(denominationLabel(l))} adedi</span><input inputmode="numeric" data-photo-count="${esc(l.id)}" aria-label="Fotoğraf ${esc(denominationLabel(l))} adedi" value="${esc(suggest.counts[l.id]??'')}" placeholder="Okunmadı"><small class="ocr-field-state ${suggest.estimates?.some(e=>e.id===l.id)?'warning':''}">${esc(suggest.sources?.[l.id]||'Okunamadı · Mevcut Adedi Kontrol Et')}</small></label>`).join('')}</div>${suggest.template?'<p class="help">Defterdeki 5 TL Satırı Kâğıt Paradır. Ayrı Madeni 5 TL Satırı Yok; Adedini Kontrol Et. Bozuk Para Tutarına Dahilse İkinci Kez Adet Girme.</p>':''}${suggest.warnings.map(w=>`<p class="warning">${esc(w)}</p>`).join('')}${suggest.estimates.length?`<div class="receipt-review"><b>Tahmin Edilen Adetler</b>${suggest.estimates.map(e=>`<p>${esc(F.lines.find(l=>l.id===e.id)?.label)}: ${e.count} Adet · ${esc(e.reason)}</p>`).join('')}<label class="switch-label"><input type="checkbox" name="acceptEstimates">Tahmin Edilen Adetleri Defterle Kontrol Ettim Ve Kabul Ediyorum</label></div>`:''}<p class="warning">Onayın yalnız forma aktarır; kapanış kaydı için ayrıca kontrol ve kaydet onayı gerekir.</p><p class="form-error" role="alert"></p><button class="primary full" type="submit">Değerleri onayla ve forma aktar</button></form>`);};
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.count){F.counts[t.dataset.count]=t.value;live();clearTimeout(timer);timer=setTimeout(stash,500);}else if(['expectedText','advanceText','otherText','note','reason'].includes(t.id)){F[t.id]=t.value;live();clearTimeout(timer);timer=setTimeout(stash,500);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal)dismiss();if(e.key==='Enter'&&e.target.matches('input[data-count]')){e.preventDefault();const inputs=[...document.querySelectorAll('input[data-count]')],i=inputs.indexOf(e.target);(inputs[i+1]||$('#otherText')).focus();}});
document.addEventListener('change',e=>{if(e.target.id==='cash'||e.target.id==='day'){stash();if(e.target.id==='cash'){selectedCash=e.target.value;posBase=0;posOriginalId=null;posOriginalDate=null;posOriginalSavedAt=0;posReason='';posValues={};posTotal='';posRead=null;singleBase=0;singleOriginalId=null;singleOriginalDate=null;singleOriginalSavedAt=0;singleAmount='';singleReason='';bankLinkedId=null;bankAmount='';bankReason='';}else selectedDate=e.target.value;loadForm();render();}else if(e.target.id==='report-cash'){reportCash=e.target.value;render();}else if(e.target.id==='period'){period=e.target.value;render();}});
