function posScreen(){if(!box())return `${browseStrip('pos',posBrowseDay)}${posDayCards()}${posRangeHtml()}${emptyCash()}`;return `<div class="hero"><h1>POS Ve Tahsilat</h1></div>${browseStrip('pos',posBrowseDay)}${posDayCards()}<h2 class="entry-heading">POS Kayıtları Ve Giriş</h2><label class="field"><span>Kasa</span><select id="cash">${cashOptions()}</select></label>${box().posMode==='total'&&!posBase?totalEntryHtml()+totalFollowupHtml():`<div class="actions"><button data-act="pos-photo">${ico('camera')} Fiş fotoğrafı yükle</button><button data-act="pos-new">${ico('plus')} Rapor ekle</button></div><details id="pos-entry" class="panel pos-entry" ${posEntryOpen||posBase?'open':''}><summary>Gün sonu raporu girişi <span>Tutarları kontrol et</span></summary><p class="help">İşlem tarihi varsayılan olarak dün. Kredi, World ve yurt dışı debit +21; yurt içi debit +16 takvim günü. Tatil ertelemesi ve komisyon uygulanmaz; gerçek banka girişi ayrıca teyit edilmelidir.</p><form id="pos-form">${photoReadSummary()}${posRead?'<p id="pos-reconciliation" class="help" role="status"></p>':''}${posBase?`<p class="warning">Kayıt düzeltmesi · r${posBase}. Kasa / POS Adı Sabit. İşlem Tarihi Gerekçeyle Değiştirilebilir; Eski Hali Saklanır.</p><label class="field"><span>Düzeltme gerekçesi</span><input name="posReason" value="${esc(posReason)}" maxlength="300" required></label>`:''}<label class="field"><span>İşlem tarihi</span><input type="date" name="posDate" value="${posDate}" max="${key()}" required></label><label class="field"><span>POS / terminal adı</span><input name="posTerminal" ${posBase?'disabled':''} maxlength="60" value="${esc(posTerminal)}" required></label>${TYPES.map(([id,label,days])=>`<label class="field"><span>${label} <small>· +${days} gün</small></span>${photoFieldStatus(id)}<input name="${id}" inputmode="decimal" value="${esc(posValues[id]||'')}" placeholder="0,00"></label>`).join('')}<label class="field"><span>Fiş genel toplamı · varsa kontrol için</span><input name="posTotal" inputmode="decimal" value="${esc(posTotal)}" placeholder="Genel toplam tekrar satışa eklenmez"></label><p class="form-error" role="alert"></p><button class="primary full" type="submit">Kontrol et ve onaya geç</button></form></details>`}${posRangeHtml()}<section class="panel"><h2>Kaydedilen POS raporları</h2><button data-act="pos-new">Yeni rapor</button>${(S.pos||[]).filter(r=>r.cashId===selectedCash).sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<div class="history-card"><b>${displayDate(r.date)} · ${esc(r.terminal)} · ${fmt(r.total)}</b><p class="help">r${r.revision||1} ${esc(r.reason||'')}</p><button data-act="pos-edit" data-id="${esc(r.id)}">Aç / gerekçeli düzelt</button></div>`).join('')}</section>`;}
