document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b)return;try{if(b.dataset.act==='pos-all'){posAll=!posAll;render();}else if(b.dataset.act==='pos-new'){posRead=null;posEntryOpen=true;posBase=0;posOriginalId=null;posOriginalDate=null;posOriginalSavedAt=0;posReason='';posDate=shift(key(),-1);posTerminal='VakıfBank';posValues={};posTotal='';render();}else if(b.dataset.act==='pos-edit'){posRead=null;posEntryOpen=true;const r=(S.pos||[]).find(r=>r.id===b.dataset.id);tab='pos';selectedCash=r.cashId;loadForm();posDate=r.date;posTerminal=r.terminal;posOriginalId=r.id;posOriginalDate=r.date;posOriginalSavedAt=r.savedAt;posBase=r.revision||1;posReason='';posValues=Object.fromEntries(r.lines.map(l=>[l.type,decimal(l.amount)]));posTotal=decimal(r.total);render();scrollTo(0,0);}else if(b.dataset.act==='pos-photo'){posToken='pos_'+Date.now().toString(36);photoContext={kind:'pos',cashId:selectedCash,token:posToken};window.KasaDenge.photo(posToken);}else if(b.dataset.act==='pos-save'){if(!pendingPos)throw Error('Onaylanacak kayıt yok.');call('savePos',JSON.stringify(pendingPos));posStart=pendingPos.lines.map(l=>l.due).sort()[0];posEnd=pendingPos.lines.map(l=>l.due).sort().slice(-1)[0];pendingPos=null;posRead=null;posEntryOpen=false;posBase=0;posOriginalId=null;posOriginalDate=null;posOriginalSavedAt=0;posReason='';posValues={};posTotal='';dismiss();refresh();toast('POS raporu kaydedildi; tahsilat takvimine eklendi.');}else if(b.dataset.act==='pos-today'){posStart=posEnd=key();render();}else if(b.dataset.act==='pos-future'){posStart=key();posEnd=shift(key(),60);render();}}catch(err){toast(err.message);}});
