document.addEventListener('input',e=>{const t=e.target,f=t.form;if(f?.id==='single-pos-form'){singleDate=f.elements.date.value;singleAmount=f.elements.amount.value;singleReason=f.elements.reason?.value||'';}else if(f?.id==='deposit-form'){bankDate=f.elements.bankDate.value;bankAmount=f.elements.amount.value;bankReason=f.elements.reason.value;}});
document.addEventListener('submit',e=>{const f=e.target;if(!['single-pos-form','deposit-form'].includes(f.id))return;e.preventDefault();try{if(f.id==='single-pos-form'){pendingTotal=totalInput(box(),singleDate,singleAmount,singleBase,singleReason);if(singleOriginalId){pendingTotal.originalId=singleOriginalId;pendingTotal.originalSavedAt=singleOriginalSavedAt;const paid=(S.settlements||[]).find(r=>r.totalId===singleOriginalId&&r.kind==='debit');if(paid&&pendingTotal.total<paid.amount)throw Error('Yeni Toplam Yatan Debit Tutarından Küçük Olamaz.');}if(singleBase&&singleReason.trim().length<3)throw Error('Düzeltme Gerekçesini Girin.');openSheet('Tek Toplam POS Onayı',`${singleDateCorrectionNotice()}<p>${esc(box().name)} · ${displayDate(singleDate)}</p><div class="ledger-row major"><span>Toplam POS</span><strong>${fmt(pendingTotal.total)}</strong></div><p class="help">Debit Tahsilatı Girilene Kadar Dağılım Bekleniyor Olarak Saklanır. Kredi Tutarı Tahmin Edilmez.</p><button class="primary full" data-act="save-single">Onaylıyorum, Kaydet</button>`);}else{pendingDeposit=matchSettlement(S.posTotals||[],S.settlements||[],selectedCash,bankDate,'debit',bankAmount,bankLinkedId);pendingDeposit.record.reason=bankReason;if(pendingDeposit.record.baseRevision&&bankReason.trim().length<3)throw Error('Debit Zaten Girilmiş. Değiştirmek İçin Düzeltme Gerekçesi Yazın.');const r=pendingDeposit;openSheet('Bulunan İşlem Ve Kredi Tutarı',`<p>${esc(cashName(r.total))} · İşlem Günü ${displayDate(r.total.date)}</p><div class="ledger-row"><span>Toplam POS</span><strong>${fmt(r.total.total)}</strong></div><div class="ledger-row"><span>Yatan Debit · ${displayDate(bankDate)}</span><strong>${fmt(r.record.amount)}</strong></div><div class="ledger-row major"><span>Beklenen Kredi · ${displayDate(shift(r.total.date,21))}</span><strong>${fmt(r.total.total-r.record.amount)}</strong></div><p class="help">Eşleşen İşlem Gününü Kontrol Et. Kredi Yatınca Tekrar Tutar Girişi İstenmez; Bu Beklenen Tutar Geçmişte Korunur.</p><button class="primary full" data-act="save-deposit">Onaylıyorum, Kaydet</button>`);}}catch(err){f.querySelector('.form-error').textContent=err.message;}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b)return;try{if(b.dataset.act==='edit-bank'){const r=(S.posTotals||[]).find(r=>r.id===b.dataset.id),d=splitTotal(r,S.settlements||[]).debit;bankLinkedId=r.id;bankDate=d.bankDate;bankAmount=decimal(d.amount);bankReason='';render();$('#deposit-form').scrollIntoView();}else if(b.dataset.act==='new-single'){singleDate=shift(key(),-1);singleBase=0;singleOriginalId=null;singleOriginalDate=null;singleOriginalSavedAt=0;singleAmount='';singleReason='';render();}else if(b.dataset.act==='save-single'){if(!pendingTotal)throw Error('Onaylanacak Toplam Yok.');call('savePosTotal',JSON.stringify(pendingTotal));pendingTotal=null;singleDate=shift(key(),-1);singleAmount='';singleBase=0;singleOriginalId=null;singleOriginalDate=null;singleOriginalSavedAt=0;singleReason='';dismiss();refresh();toast('Toplam POS Kaydedildi.');}else if(b.dataset.act==='save-deposit'){if(!pendingDeposit)throw Error('Onaylanacak Tahsilat Yok.');call('receivePos',JSON.stringify(pendingDeposit.record));posStart=posEnd=shift(pendingDeposit.total.date,21);pendingDeposit=null;bankLinkedId=null;bankAmount='';bankReason='';dismiss();refresh();toast('Debit Kaydedildi. Beklenen Kredi Takvime Eklendi.');}else if(b.dataset.act==='edit-single'){const r=(S.posTotals||[]).find(r=>r.id===b.dataset.id);tab='pos';selectedCash=r.cashId;loadForm();singleOriginalId=r.id;singleOriginalDate=r.date;singleOriginalSavedAt=r.savedAt;singleDate=r.date;singleAmount=decimal(r.total);singleBase=r.revision;singleReason='';render();scrollTo(0,0);}}catch(err){toast(err.message);}});

refresh();

function decorateDates(){document.querySelectorAll('input[type="date"]:not(.browse-date-input)').forEach(input=>{if(!input.parentElement.classList.contains('date-control')){const wrap=document.createElement('div');wrap.className='date-control';input.before(wrap);wrap.append(input);const face=document.createElement('span');face.className='date-face';face.setAttribute('aria-hidden','true');wrap.append(face);}input.parentElement.querySelector('.date-face').textContent=displayDate(input.value);});}
document.addEventListener('change',e=>{if(e.target.type==='date')decorateDates();});

document.addEventListener('toggle',e=>{if(e.target.id==='pos-entry')posEntryOpen=e.target.open;},true);

function decorateLabels(){const selectors='h1,h2,h3,button,label>span,summary,th,option,.badge,.ledger-row>span,.metric-card>small,.hero-state,.hero-facts small,.denom-chip,.settings-row b,.today-pos b,.other-needed>span';document.querySelectorAll(selectors).forEach(el=>{const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement.closest('svg,textarea,pre'))continue;node.textContent=titleCase(node.textContent);}});}
function decorateAmounts(){document.querySelectorAll('input[inputmode="decimal"]').forEach(input=>{input.dataset.money='true';if(input.value.trim())try{input.value=amountText(money(input.value));}catch{}});}
document.addEventListener('focusout',e=>{const t=e.target;if(!t.matches('input[inputmode="decimal"]')||!t.value.trim())return;try{t.value=amountText(money(t.value));t.dispatchEvent(new Event('input',{bubbles:true}));}catch(err){toast(err.message);}});

function photoReadSummary(){if(!posRead)return '';const read=Object.values(posRead.amounts).filter(v=>v!==null).length;return `<div class="receipt-review ${posRead.matched?'matched':'needs-review'}"><b>${posRead.matched?'Fiş Toplamı Uyuşuyor':'Fiş Okumasını Kontrol Et'}</b><p>${read} Tutar Okundu · ${posRead.missing.length} Bölümde Tutar Eksik · ${posRead.unassigned.length} Eşleşmeyen Satır</p><div class="ledger-row"><span>Okunan Tutarlar Toplamı</span><strong>${fmt(posRead.sum)}</strong></div><div class="ledger-row"><span>Fiş Genel Toplamı</span><strong>${posRead.total===null?'Okunamadı':fmt(posRead.total)}</strong></div><small>${posRead.total===null?'Genel Toplam Girilmeden Fotoğraf Kaydı Onaylanamaz.':posRead.sum!==posRead.total?'Tutarlar Uyuşmadan Kayıt Yapılmaz.':''} Bulunamayan Alanlar Tahmin Edilmez; Görünmeyen Kategori Sıfır Kabul Edilmez.</small></div>`;}
function photoFieldStatus(id){if(!posRead)return '';const seen=posRead.seenTypes.includes(id),value=posRead.amounts[id];return `<small class="ocr-field-state ${seen&&(value===undefined||value===null)?'neg':''}">${seen?(value===undefined||value===null?'Fişte Bölüm Var · Tutar Okunamadı':'Okundu · Kontrol Et'):'Fişte Bu Bölüm Bulunamadı'}</small>`;}

function updatePosReconciliation(){const el=$('#pos-reconciliation');if(!el||!posRead)return;try{const total=posTotal.trim()?money(posTotal):null,sum=TYPES.reduce((n,[id])=>n+(posValues[id]?.trim()?money(posValues[id]):0),0);el.textContent=total===null?'Fiş Genel Toplamını Girin.':sum===total?'Düzenlenen Tutarlar Fiş Genel Toplamıyla Uyuşuyor.':'Düzenlenen Toplam: '+fmt(sum)+' · Fişle Fark: '+fmt(sum-total);el.className='help '+(total!==null&&sum===total?'ok':'warning');}catch{el.textContent='Tutarları Kontrol Edin.';el.className='warning';}}

function signedMoney(n){return (n>0?'+':'')+fmt(n);}
function renderDailyReconciliation(){const el=$('#count-focus');if(el)el.innerHTML=cashDayCards();}


function singleDateCorrectionNotice(){if(!singleOriginalDate||singleOriginalDate===singleDate)return '';const d=(S.settlements||[]).find(r=>r.totalId===singleOriginalId&&r.kind==='debit');return `<p class="warning">İşlem Tarihi ${displayDate(singleOriginalDate)} → ${displayDate(singleDate)} Değişecek. Kredi Vadesi ${displayDate(shift(singleDate,21))} Olacak.</p>${d?`<div class="ledger-row"><span>Korunan Gerçek Debit Yatış Tarihi</span><strong>${displayDate(d.bankDate)}</strong></div><div class="ledger-row"><span>Korunan Yatan Debit Tutarı</span><strong>${fmt(d.amount)}</strong></div><p class="help">Banka Yatışı Değişmez. Tahsilatın İşlem Günü Bağı Gerekçeli Olarak Düzeltilecek.</p>`:'<p class="help">Debit Henüz Girilmedi; Dağılım Beklenmeye Devam Edecek.</p>'}`;}
// Android WebView date inputs use the platform calendar; browser keeps its native input.
let dateTarget=null;
document.addEventListener('click',e=>{const input=e.target.closest('input[type="date"]');if(!input||input.disabled||typeof window.KasaDenge?.pickDate!=='function')return;e.preventDefault();const token='date_'+Date.now()+'_'+Math.random();dateTarget={input,token};window.KasaDenge.pickDate(input.value,input.max||'',token);});
window.dateResult=result=>{if(!dateTarget||result.token!==dateTarget.token)return;const {input}=dateTarget;dateTarget=null;if(!input.isConnected||input.disabled||!result.date)return;input.value=result.date;input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));};
document.addEventListener('submit',e=>{if(e.target.id!=='pos-photo-date-form')return;e.preventDefault();try{const value=e.target.elements.receiptDate.value;if(!value||key(date(value))!==value||value>key())throw Error('Bugün veya geçmiş bir işlem tarihi seçin.');posDate=value;dismiss();render();}catch(err){e.target.querySelector('.form-error').textContent=err.message;}});

function percentBadge(value,reason=null){return value===null?`<small class="weekly-badge unavailable" title="${esc(reason||'Karşılaştırma Yok')}">−</small>`:`<span class="weekly-badge ${value>0?'increase':value<0?'decrease':'unchanged'}">${value>0?'↑ ':value<0?'↓ ':''}%${Math.abs(value).toLocaleString('tr-TR',{minimumFractionDigits:1,maximumFractionDigits:1})}</span>`;}
function browseStrip(kind,day){return `<section class="day-browser" data-browse="${kind}" aria-label="${kind==='cash'?'Nakit':'POS'} Görüntüleme Tarihi"><button data-act="browse-prev" data-kind="${kind}" aria-label="Önceki Gün">‹</button><button class="browse-date" data-act="browse-pick" data-kind="${kind}" aria-label="${kind==='cash'?'Nakit':'POS'} Takvimini Aç"><span>📆</span> ${new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric',weekday:'long'}).format(date(day))}</button><button data-act="browse-next" data-kind="${kind}" ${kind==='cash'&&day>=key()?'disabled':''} aria-label="Sonraki Gün">›</button><input class="browse-date-input" type="date" id="browse-${kind}" aria-label="${kind==='cash'?'Nakit':'POS'} Görüntüleme Tarihi Seç" value="${day}" ${kind==='cash'?`max="${key()}"`:''}></section><p class="browse-caption">Günler Arasında Kaydır · Yüzdeler Geçen Haftanın Aynı Gününe Göre</p>`;}
function cashDayCards(){const d=cashDay(S.entries,cashBrowseDay);return `<section class="browse-hero"><small>KASALAR NAKİT TOPLAMI</small><div class="browse-amount"><b>${d.rows.length?fmt(d.total):'— TL'}</b>${percentBadge(d.pct)}</div><p>Avans Hariç · Kayıtlı Sayımlar</p><div class="browse-diff"><span>Günlük Fark</span><b class="${d.diff<0?'decrease':d.diff>0?'increase':''}">${signedMoney(d.diff)}</b></div></section><section class="panel saved-cash-card"><h2>Seçilen Günün Kasaları</h2>${d.rows.map(r=>`<div class="saved-cash-row"><b>${esc(cashName(r))}</b><div><strong>${fmt(r.net)}</strong>${percentBadge(r.pct)}</div><strong class="${r.diff<0?'decrease':r.diff>0?'increase':''}">${r.diff===0?'Dengeli':signedMoney(r.diff)}</strong></div>`).join('')||'<p class="help">Bu Gün İçin Kaydedilmiş Sayım Yok.</p>'}<p class="help">Yalnız Kaydedilmiş Sayımlar · Taslaklar Dahil Değil.${d.scopeMismatch?' Kasa Kapsamı Farklı; Mevcut Kayıtlı Tutarlar Karşılaştırıldı.':''}</p></section>`;}
function posDayCards(){const d=posDay(allPos(),posBrowseDay);return `<section class="browse-hero"><small>SEÇİLEN GÜN YATACAK POS</small><div class="browse-amount"><b>${d.rows.length?fmt(d.total):'— TL'}</b>${percentBadge(d.changes.total,d.reasons.total)}</div><div class="browse-type"><span>Kredi Kartı</span><strong>${fmt(d.credit)}</strong>${percentBadge(d.changes.credit,d.reasons.credit)}</div><div class="browse-type"><span>Debit Kart</span><strong>${fmt(d.debit)}</strong>${percentBadge(d.changes.debit,d.reasons.debit)}</div></section><section class="day-pos-cards">${d.rows.map(r=>`<article class="panel"><div class="pos-day-heading"><h2>${esc(cashName(r))}</h2><strong>${fmt(r.total)}</strong>${percentBadge(r.changes.total,r.reasons.total)}</div><div class="browse-type"><span>Kredi Kartı</span><strong>${fmt(r.credit)}</strong>${percentBadge(r.changes.credit,r.reasons.credit)}</div><div class="browse-type"><span>Debit Kart</span><strong>${fmt(r.debit)}</strong>${percentBadge(r.changes.debit,r.reasons.debit)}</div></article>`).join('')||'<p class="panel help">Bu Gün İçin Kayıtlı Beklenen POS Ödemesi Yok.</p>'}</section><p class="help">Aynı Kasadaki POS Kayıtları Birleştirilir.${d.incomplete?' Dağılım Bekleniyor; Mevcut Tutarlarla Karşılaştırıldı. Dağılım Girilince Yüzdeler Güncellenir.':''}${d.scopeMismatch?' Kasa Kapsamı Farklı; Mevcut Kayıtlı Tutarlar Karşılaştırıldı.':''}</p>`;}
function setBrowse(kind,day){if(key(date(day))!==day||kind==='cash'&&day>key())return;if(kind==='cash')cashBrowseDay=day;else posBrowseDay=day;render();}
let browseGesture=null,suppressBrowseClick=0,suppressBrowseKind=null;
document.addEventListener('pointerdown',e=>{const strip=e.target.closest('[data-browse]');if(strip)browseGesture={kind:strip.dataset.browse,x:e.clientX,y:e.clientY};});
document.addEventListener('pointerup',e=>{const g=browseGesture;browseGesture=null;if(!g)return;const dx=e.clientX-g.x,dy=e.clientY-g.y;if(Math.abs(dx)<50||Math.abs(dx)<Math.abs(dy)*1.5)return;suppressBrowseClick=Date.now()+400;suppressBrowseKind=g.kind;setBrowse(g.kind,shift(g.kind==='cash'?cashBrowseDay:posBrowseDay,dx<0?1:-1));});
document.addEventListener('pointercancel',()=>browseGesture=null);
document.addEventListener('click',e=>{const b=e.target.closest('[data-act^="browse-"]');if(!b)return;if(Date.now()<suppressBrowseClick&&b.dataset.kind===suppressBrowseKind){e.preventDefault();e.stopImmediatePropagation();return;}const kind=b.dataset.kind,day=kind==='cash'?cashBrowseDay:posBrowseDay;if(b.dataset.act==='browse-pick'){const input=$('#browse-'+kind);if(typeof window.KasaDenge?.pickDate==='function')input.click();else if(input.showPicker)input.showPicker();else input.click();}else setBrowse(kind,shift(day,b.dataset.act==='browse-next'?1:-1));},true);
document.addEventListener('change',e=>{if(e.target.id==='browse-cash'||e.target.id==='browse-pos')setBrowse(e.target.id.slice(7),e.target.value);});

function commentCard(c){return `<article class="insight ${c.tone==='warning'?'analysis-warning':''}"><h3>${esc(c.title)}</h3><p>${esc(c.text)}</p></article>`;}
function weekdayChart(title,rows,caption){const max=Math.max(1,...rows.map(r=>Math.max(0,r.avg||0)));return `<section class="panel weekday-chart"><h2>${title}</h2><p class="help">${caption} · Son 12 Hafta · Kayıtlı Gün Ortalaması. Eksik Günler Sıfır Sayılmaz.</p><div class="bars">${rows.map((r,i)=>`<div class="bar"><i style="height:${r.avg===null?3:Math.max(3,Math.max(0,r.avg)/max*100)}px"></i>${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'][i]}<br>${r.count} Gün</div>`).join('')}</div><div class="weekday-values">${rows.map((r,i)=>`<div class="ledger-row"><span>${['Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi','Pazar'][i]}</span><strong>${r.avg===null?'Kayıt Yok':fmt(Math.round(r.avg))}</strong></div>`).join('')}</div></section>`;}

function historyFolder(id,title,body){return `<details class="history-folder" data-history="${esc(id)}" ${expandedHistory.has(id)?'open':''}><summary>${title}</summary>${body}</details>`;}
function historyScreen(){const cashNet=S.entries.reduce((n,r)=>n+r.diff,0),cashYears=periodTree(S.entries),posYears=periodTree(allPos());const monthName=m=>new Intl.DateTimeFormat('tr-TR',{month:'long',year:'numeric'}).format(date(m+'-01'));const folder=(type,years)=>years.map(y=>historyFolder(type+'-'+y.year,y.year,y.months.map(m=>historyFolder(type+'-'+m.month,`${esc(monthName(m.month))} <b class="${type==='cash'?(m.net<0?'neg':'pos'):''}">${type==='cash'?signedMoney(m.net):fmt(m.total)}</b>`,type==='cash'?`<div class="month-net"><small>Aylık Net Kasa Farkı</small><strong>${m.net===0?'Dengeli':fmt(Math.abs(m.net))+(m.net<0?' Kasa Eksiği':' Kasa Fazlası')}</strong></div>${cashMonthBoxes(m.rows)}${cashHistoryDays(m.rows)}`:posHistoryRows(m.rows))).join(''))).join('');return `<div class="toolbar"><h1>Nakit Ve POS Geçmişi</h1></div><section class="panel month-net"><small>Tüm Kayıtların Net Kasa Farkı</small><strong class="${cashNet<0?'neg':'pos'}">${cashNet===0?'Dengeli':fmt(Math.abs(cashNet))+(cashNet<0?' Kasa Eksiği':' Kasa Fazlası')}</strong></section><section class="panel history-list">${historyFolder('cash','Nakit',folder('cash',cashYears)||'<p class="help">Kayıt Yok.</p>')}${historyFolder('pos','POS',folder('pos',posYears)||'<p class="help">POS Kaydı Yok.</p>')}</section>`;}
function cashMonthBoxes(rows){const ids=[...new Set(rows.map(r=>r.cashId))];return ids.map(id=>{const net=rows.filter(r=>r.cashId===id).reduce((n,r)=>n+r.diff,0);return `<div class="ledger-row"><span>${esc(cashName({cashId:id}))}</span><strong class="${net<0?'neg':'pos'}">${signedMoney(net)}</strong></div>`;}).join('');}
function posHistoryRows(rows){return [...rows].sort((a,b)=>b.date.localeCompare(a.date)).map(r=>{const credit=r.lines.filter(l=>!l.type.startsWith('debit')).reduce((n,l)=>n+l.amount,0),debit=r.lines.filter(l=>l.type.startsWith('debit')).reduce((n,l)=>n+l.amount,0);return `<article class="history-card"><b>${displayDate(r.date)} · ${esc(cashName(r))}</b><div class="ledger-row"><span>Toplam POS Satışı</span><strong>${fmt(r.total)}</strong></div>${r.singleTotal&&!r.lines.length?'<p class="help">Kart Dağılımı Henüz Girilmedi.</p>':`<p>Kredi Kartı ${fmt(credit)} · Debit Kart ${fmt(debit)}</p>`}<button data-act="${r.singleTotal?'edit-single':'pos-edit'}" data-id="${esc(r.id)}">Aç / Gerekçeli Düzelt</button></article>`;}).join('');}
document.addEventListener('toggle',e=>{const id=e.target.dataset?.history;if(id){if(e.target.open)expandedHistory.add(id);else expandedHistory.delete(id);}},true);

function posRangeHtml(){const rows=schedule(allPos(),posStart,posEnd,rangeCash==='all'?null:rangeCash),total=rows.reduce((s,l)=>s+l.amount,0);const groups=new Map();for(const l of rows){const id=l.due+'_'+l.cashId+'_'+l.terminal;let g=groups.get(id);if(!g){g={...l,total:0,lines:[]};groups.set(id,g);}g.total+=l.amount;g.lines.push(l);}return `<section class="panel"><h2>Tarih Aralığında Yatacak POS</h2><label class="field"><span>Tahsilat Kasası</span><select id="range-cash" aria-label="Tahsilat Kasası"><option value="all" ${rangeCash==='all'?'selected':''}>Tüm Kasalar</option>${cfg().cashboxes.map(b=>`<option value="${esc(b.id)}" ${rangeCash===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><div class="actions"><button data-act="pos-today">Bugün</button><button data-act="pos-future">İleri tarihler · 60 gün</button></div><div class="money-fields"><label class="field"><span>Başlangıç · dahil</span><input id="pos-start" type="date" value="${posStart}"></label><label class="field"><span>Bitiş · dahil</span><input id="pos-end" type="date" value="${posEnd}"></label></div><div class="metric-card"><small>${displayDate(posStart)} – ${displayDate(posEnd)} · ${rangeCash==='all'?'Tüm Kasalar':esc(cashName({cashId:rangeCash}))} · Toplam Yatacak POS</small><b>${fmt(total)}</b></div>${[...groups.values()].map(g=>`<article class="history-card"><b>${g.due.split('-').reverse().join('.')} · ${esc(g.cashName)}</b><div class="ledger-row"><span>${esc(g.terminal)}</span><strong>${fmt(g.total)}</strong></div>${g.lines.map(l=>`<p class="help">${esc(denominationLabel(l))}: ${fmt(l.amount)} · işlem ${displayDate(l.date)}</p>`).join('')}</article>`).join('')||'<p class="help">Bu aralıkta kayıtlı beklenen ödeme yok. Eksik raporlar sıfır satış anlamına gelmez.</p>'}</section>`;}
